  if (expectedNetworkId === undefined) return
  if (client.networkID !== expectedNetworkId) {
    throw new IssuerError(
      `Connected to network ${client.networkID ?? 'unknown'} but expected ${expectedNetworkId}; refusing to sign`,
    )
