import { open, rename } from 'node:fs/promises'
import { resolve } from 'node:path'

import { Client, ECDSA, Wallet, validateMPTokenMetadata, xrpToDrops, type MPTokenMetadata } from 'xrpl'

import {
  type AuditEvent,
  type HolderStatus,
  JsonFileBanRegistry,
  MptIssuer,
  PolicyViolationError,
  type ValidatedTx,
  optIn,
  sendMpt,
  submitAndValidate,
  submitOrThrow,
} from './index.js'

const PROJECT_DIR = resolve(import.meta.dirname, '..')
const HOLDER_FUNDING_XRP = '3'

const METADATA: MPTokenMetadata = {
  ticker: 'DUSD',
  name: 'Demo Regulated USD',
  desc: 'Testnet demo of a permissioned, stablecoin-style MPT with allowlist, freeze, clawback and bans.',
  icon: 'https://example.com/dusd.png',
  asset_class: 'rwa',
  asset_subclass: 'stablecoin',
  issuer_name: 'Demo Issuer',
}

function env(name: string): string {
  const value = process.env[name]
  if (!value) throw new Error(`Missing environment variable ${name} (see .env.example)`)
  return value
}

function step(title: string): void {
  console.log(`\n=== ${title}`)
}

function check(condition: boolean, message: string): void {
  if (!condition) throw new Error(`CHECK FAILED: ${message}`)
  console.log(`  ✔ ${message}`)
}

function expectResult(tx: ValidatedTx, expected: string, what: string): void {
  check(tx.resultCode === expected, `${what} → ${tx.resultCode} (expected ${expected}, tx ${tx.hash})`)
}

async function expectPolicyRefusal(promise: Promise<unknown>, what: string): Promise<void> {
  try {
    await promise
  } catch (err) {
    if (err instanceof PolicyViolationError) {
      check(true, `${what} refused by module: ${err.message}`)
      return
    }
    throw err
  }
  throw new Error(`CHECK FAILED: ${what} was expected to be refused`)
}

function expectHolder(status: HolderStatus, expected: Partial<HolderStatus>, label: string): void {
  for (const [key, value] of Object.entries(expected)) {
    const actual = status[key as keyof HolderStatus]
    check(actual === value, `${label}.${key} = ${String(actual)}`)
  }
}

async function writeFileAtomic(path: string, contents: string, mode = 0o644): Promise<void> {
  const tmp = `${path}.${process.pid}.tmp`
  const file = await open(tmp, 'w', mode)
  try {
    await file.writeFile(contents, 'utf8')
    await file.sync()
  } finally {
    await file.close()
  }
  await rename(tmp, path)
}

